Literal.Value:
'{
  "params": [
    {
      "name": "colorGood",
      "expr": "pbiColor(''good'')"
    },
    {
      "name": "colorBad",
      "expr": "pbiColor(''bad'')"
    },
    {
      "name": "colorNoBudget",
      "expr": "pbiColor(''neutral'')"
    },
    {
      "name": "colorLastYear",
      "value": "#C8C6C4"
    },
    {
      "name": "lastYearOpacity",
      "value": 0.6
    },
    {
      "name": "colorTarget",
      "value": "#252423"
    },
    {
      "name": "colorValueInside",
      "value": "#FFFFFF"
    },
    {
      "name": "colorValueOutside",
      "value": "#252423"
    },
    {
      "name": "colorCategoryText",
      "value": "#252423"
    },
    {
      "name": "colorAxisText",
      "value": "#605E5C"
    },
    {
      "name": "colorGrid",
      "value": "#C8C6C4"
    },
    {
      "name": "valueFormat",
      "value": ".3s"
    },
    {
      "name": "varianceFormat",
      "value": ".1%"
    },
    {
      "name": "axisFormat",
      "value": "~s"
    },
    {
      "name": "tooltipValueFormat",
      "value": ",.0f"
    },
    {
      "name": "tooltipPercentFormat",
      "value": ".1%"
    },
    {
      "name": "valueLabelPosition",
      "value": "end"
    },
    {
      "name": "labelFontSize",
      "value": 12
    },
    {
      "name": "labelPadding",
      "value": 5
    },
    {
      "name": "categoryFontSize",
      "value": 12
    },
    {
      "name": "categoryLabelLimit",
      "value": 200
    },
    {
      "name": "axisFontSize",
      "value": 11
    },
    {
      "name": "actualBarBand",
      "value": 0.5
    },
    {
      "name": "lastYearBand",
      "value": 0.9
    },
    {
      "name": "rowPadding",
      "value": 0.1
    },
    {
      "name": "barCornerRadius",
      "value": 4
    },
    {
      "name": "targetThickness",
      "value": 3
    },
    {
      "name": "labelGutter",
      "expr": "targetThickness / 2 + 3 * labelPadding + 7 * labelFontSize * 0.56 + (bandwidth(''y'') * actualBarBand < labelFontSize * 0.8 ? 6 * labelFontSize * 0.56 + 2 * labelPadding : 0)"
    }
  ],
  "data": {
    "name": "dataset"
  },
  "transform": [
    {
      "calculate": "isValid(datum[''Budget''])",
      "as": "hasBudget"
    },
    {
      "calculate": "isValid(datum[''Actual'']) && isValid(datum[''Budget'']) ? datum[''Actual''] - datum[''Budget''] : null",
      "as": "varBudget"
    },
    {
      "calculate": "isValid(datum.varBudget) && datum[''Budget''] !== 0 ? datum.varBudget / abs(datum[''Budget'']) : null",
      "as": "varBudgetPct"
    },
    {
      "calculate": "isValid(datum[''Actual'']) && isValid(datum[''Last Year'']) ? datum[''Actual''] - datum[''Last Year''] : null",
      "as": "varLastYear"
    },
    {
      "calculate": "isValid(datum.varLastYear) && datum[''Last Year''] !== 0 ? datum.varLastYear / abs(datum[''Last Year'']) : null",
      "as": "varLastYearPct"
    },
    {
      "calculate": "!isValid(datum.varBudget) ? ''none'' : datum.varBudget >= 0 ? ''good'' : ''bad''",
      "as": "status"
    },
    {
      "calculate": "isValid(datum[''Actual'']) ? format(datum[''Actual''], valueFormat) : ''''",
      "as": "valueText"
    },
    {
      "calculate": "length(datum.valueText) * labelFontSize * 0.56",
      "as": "valueTextWidth"
    },
    {
      "calculate": "isValid(datum.varBudgetPct) ? (datum.status === ''good'' ? ''+'' : ''-'') + format(abs(datum.varBudgetPct), varianceFormat) : ''''",
      "as": "varianceText"
    },
    {
      "calculate": "isValid(datum[''Actual'']) ? format(datum[''Actual''], tooltipValueFormat) : ''''",
      "as": "tipActual"
    },
    {
      "calculate": "isValid(datum[''Budget'']) ? format(datum[''Budget''], tooltipValueFormat) : ''''",
      "as": "tipBudget"
    },
    {
      "calculate": "isValid(datum[''Last Year'']) ? format(datum[''Last Year''], tooltipValueFormat) : ''''",
      "as": "tipLastYear"
    },
    {
      "calculate": "isValid(datum.varBudget) ? (datum.varBudget >= 0 ? ''+'' : ''-'') + format(abs(datum.varBudget), tooltipValueFormat) : ''''",
      "as": "tipVarBudget"
    },
    {
      "calculate": "isValid(datum.varBudgetPct) ? (datum.varBudgetPct >= 0 ? ''+'' : ''-'') + format(abs(datum.varBudgetPct), tooltipPercentFormat) : ''''",
      "as": "tipVarBudgetPct"
    },
    {
      "calculate": "isValid(datum.varLastYear) ? (datum.varLastYear >= 0 ? ''+'' : ''-'') + format(abs(datum.varLastYear), tooltipValueFormat) : ''''",
      "as": "tipVarLastYear"
    },
    {
      "calculate": "isValid(datum.varLastYearPct) ? (datum.varLastYearPct >= 0 ? ''+'' : ''-'') + format(abs(datum.varLastYearPct), tooltipPercentFormat) : ''''",
      "as": "tipVarLastYearPct"
    },
    {
      "window": [
        {
          "op": "row_number",
          "as": "rowOrder"
        }
      ],
      "sort": [
        {
          "field": "Actual",
          "order": "descending"
        },
        {
          "field": "Category",
          "order": "ascending"
        }
      ]
    }
  ],
  "encoding": {
    "y": {
      "field": "Category",
      "type": "nominal",
      "sort": {
        "field": "rowOrder",
        "op": "min",
        "order": "ascending"
      },
      "scale": {
        "paddingInner": {
          "expr": "rowPadding"
        },
        "paddingOuter": {
          "expr": "rowPadding / 2"
        }
      },
      "axis": {
        "title": null,
        "ticks": false,
        "domain": true,
        "domainColor": {
          "expr": "colorGrid"
        },
        "labelColor": {
          "expr": "colorCategoryText"
        },
        "labelFontSize": {
          "expr": "categoryFontSize"
        },
        "labelLimit": {
          "expr": "categoryLabelLimit"
        },
        "labelPadding": 8,
        "labelOverlap": true
      }
    },
    "tooltip": [
      {
        "field": "Category",
        "type": "nominal"
      },
      {
        "field": "tipActual",
        "type": "nominal",
        "title": "Actual"
      },
      {
        "field": "tipBudget",
        "type": "nominal",
        "title": "Budget"
      },
      {
        "field": "tipLastYear",
        "type": "nominal",
        "title": "Last Year"
      },
      {
        "field": "tipVarBudget",
        "type": "nominal",
        "title": "Var to Budget"
      },
      {
        "field": "tipVarBudgetPct",
        "type": "nominal",
        "title": "Var to Budget %"
      },
      {
        "field": "tipVarLastYear",
        "type": "nominal",
        "title": "Var to Last Year"
      },
      {
        "field": "tipVarLastYearPct",
        "type": "nominal",
        "title": "Var to Last Year %"
      }
    ]
  },
  "layer": [
    {
      "description": "Last Year bar, wide and light, behind",
      "mark": {
        "type": "bar",
        "height": {
          "expr": "bandwidth(''y'') * lastYearBand"
        },
        "color": {
          "expr": "colorLastYear"
        },
        "opacity": {
          "expr": "lastYearOpacity"
        }
      },
      "encoding": {
        "x": {
          "field": "Last Year",
          "type": "quantitative",
          "scale": {
            "zero": true,
            "nice": true,
            "range": [
              0,
              {
                "expr": "max(width - labelGutter, width / 2)"
              }
            ]
          },
          "axis": {
            "title": null,
            "ticks": false,
            "domain": false,
            "tickCount": 5,
            "labelExpr": "format(datum.value, axisFormat)",
            "labelColor": {
              "expr": "colorAxisText"
            },
            "labelFontSize": {
              "expr": "axisFontSize"
            },
            "labelFlush": false,
            "grid": true,
            "gridColor": {
              "expr": "colorGrid"
            },
            "gridDash": [
              1,
              4
            ]
          }
        }
      }
    },
    {
      "description": "Actual bar, coloured by the Budget test",
      "mark": {
        "type": "bar",
        "height": {
          "expr": "bandwidth(''y'') * actualBarBand"
        },
        "cornerRadiusEnd": {
          "expr": "barCornerRadius"
        },
        "color": {
          "expr": "datum.status === ''good'' ? colorGood : datum.status === ''bad'' ? colorBad : colorNoBudget"
        }
      },
      "encoding": {
        "x": {
          "field": "Actual",
          "type": "quantitative"
        }
      }
    },
    {
      "description": "Budget target tick",
      "mark": {
        "type": "tick",
        "size": {
          "expr": "bandwidth(''y'') * lastYearBand"
        },
        "thickness": {
          "expr": "targetThickness"
        },
        "color": {
          "expr": "colorTarget"
        },
        "opacity": 1
      },
      "encoding": {
        "x": {
          "field": "Budget",
          "type": "quantitative"
        }
      }
    },
    {
      "description": "Actual value label: inside the bar when it fits, outside in dark text when not",
      "mark": {
        "type": "text",
        "align": "left",
        "baseline": "middle",
        "fontSize": {
          "expr": "labelFontSize"
        },
        "dx": {
          "expr": "(((bandwidth(''y'') * actualBarBand) >= labelFontSize * 0.8 && (valueLabelPosition === ''base'' ? (scale(''x'', datum[''Actual'']) >= datum.valueTextWidth + 2 * labelPadding && !(datum.hasBudget && scale(''x'', datum[''Budget'']) - (targetThickness / 2) < datum.valueTextWidth + 2 * labelPadding)) : ((datum.hasBudget && scale(''x'', datum[''Budget'']) < scale(''x'', datum[''Actual'']) && scale(''x'', datum[''Budget'']) + (targetThickness / 2) > scale(''x'', datum[''Actual'']) - datum.valueTextWidth - 2 * labelPadding ? scale(''x'', datum[''Budget'']) - (targetThickness / 2) - labelPadding : scale(''x'', datum[''Actual'']) - labelPadding) - datum.valueTextWidth >= labelPadding))) ? (valueLabelPosition === ''base'' ? labelPadding : (datum.hasBudget && scale(''x'', datum[''Budget'']) < scale(''x'', datum[''Actual'']) && scale(''x'', datum[''Budget'']) + (targetThickness / 2) > scale(''x'', datum[''Actual'']) - datum.valueTextWidth - 2 * labelPadding ? scale(''x'', datum[''Budget'']) - (targetThickness / 2) - labelPadding : scale(''x'', datum[''Actual'']) - labelPadding) - datum.valueTextWidth) : (datum.hasBudget && scale(''x'', datum[''Budget'']) + (targetThickness / 2) >= scale(''x'', datum[''Actual'']) && scale(''x'', datum[''Budget'']) - (targetThickness / 2) < scale(''x'', datum[''Actual'']) + 2 * labelPadding + datum.valueTextWidth ? scale(''x'', datum[''Budget'']) + (targetThickness / 2) + labelPadding : scale(''x'', datum[''Actual'']) + labelPadding)) - scale(''x'', datum[''Actual''])"
        },
        "color": {
          "expr": "((bandwidth(''y'') * actualBarBand) >= labelFontSize * 0.8 && (valueLabelPosition === ''base'' ? (scale(''x'', datum[''Actual'']) >= datum.valueTextWidth + 2 * labelPadding && !(datum.hasBudget && scale(''x'', datum[''Budget'']) - (targetThickness / 2) < datum.valueTextWidth + 2 * labelPadding)) : ((datum.hasBudget && scale(''x'', datum[''Budget'']) < scale(''x'', datum[''Actual'']) && scale(''x'', datum[''Budget'']) + (targetThickness / 2) > scale(''x'', datum[''Actual'']) - datum.valueTextWidth - 2 * labelPadding ? scale(''x'', datum[''Budget'']) - (targetThickness / 2) - labelPadding : scale(''x'', datum[''Actual'']) - labelPadding) - datum.valueTextWidth >= labelPadding))) && datum.status !== ''none'' ? colorValueInside : colorValueOutside"
        },
        "opacity": {
          "expr": "bandwidth(''y'') >= labelFontSize ? 1 : 0"
        }
      },
      "encoding": {
        "x": {
          "field": "Actual",
          "type": "quantitative"
        },
        "text": {
          "field": "valueText"
        }
      }
    },
    {
      "description": "Variance to Budget label, signed and coloured by the same test as the bar",
      "mark": {
        "type": "text",
        "align": "left",
        "baseline": "middle",
        "fontSize": {
          "expr": "labelFontSize"
        },
        "fontWeight": 600,
        "dx": {
          "expr": "max(((bandwidth(''y'') * actualBarBand) >= labelFontSize * 0.8 && (valueLabelPosition === ''base'' ? (scale(''x'', datum[''Actual'']) >= datum.valueTextWidth + 2 * labelPadding && !(datum.hasBudget && scale(''x'', datum[''Budget'']) - (targetThickness / 2) < datum.valueTextWidth + 2 * labelPadding)) : ((datum.hasBudget && scale(''x'', datum[''Budget'']) < scale(''x'', datum[''Actual'']) && scale(''x'', datum[''Budget'']) + (targetThickness / 2) > scale(''x'', datum[''Actual'']) - datum.valueTextWidth - 2 * labelPadding ? scale(''x'', datum[''Budget'']) - (targetThickness / 2) - labelPadding : scale(''x'', datum[''Actual'']) - labelPadding) - datum.valueTextWidth >= labelPadding))) ? scale(''x'', datum[''Actual'']) + labelPadding : (datum.hasBudget && scale(''x'', datum[''Budget'']) + (targetThickness / 2) >= scale(''x'', datum[''Actual'']) && scale(''x'', datum[''Budget'']) - (targetThickness / 2) < scale(''x'', datum[''Actual'']) + 2 * labelPadding + datum.valueTextWidth ? scale(''x'', datum[''Budget'']) + (targetThickness / 2) + labelPadding : scale(''x'', datum[''Actual'']) + labelPadding) + datum.valueTextWidth + 2 * labelPadding, datum.hasBudget ? scale(''x'', datum[''Budget'']) + (targetThickness / 2) + labelPadding : 0) - scale(''x'', datum[''Actual''])"
        },
        "color": {
          "expr": "datum.status === ''good'' ? colorGood : datum.status === ''bad'' ? colorBad : colorNoBudget"
        },
        "opacity": {
          "expr": "bandwidth(''y'') >= labelFontSize ? 1 : 0"
        }
      },
      "encoding": {
        "x": {
          "field": "Actual",
          "type": "quantitative"
        },
        "text": {
          "field": "varianceText"
        }
      }
    }
  ]
}'
